  // 2.17.10: Meal alert -> Resident Food Intake with the Guest, meal and date already chosen.
  const mealTaskContext = a => {
    const title=String(a?.title||'').toLowerCase();
    const meal_type=title.includes('breakfast')?'Tiffin':title.includes('lunch')?'Lunch':title.includes('dinner')?'Dinner':'';
    let meal_date='',hour=null;
    try{const d=new Date(a?.due_at);if(!Number.isNaN(d.getTime())){meal_date=d.toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});hour=Number(d.toLocaleString('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',hour12:false}))}}catch(_error){}
    // Escalation register rows carry no title: Meal Due times are 8 AM / 1 PM / 8 PM.
    const byHour=hour===8?'Tiffin':hour===13?'Lunch':hour===20?'Dinner':'';
    return {meal_type:meal_type||(String(a?.alert_type||'').toLowerCase()==='meal'?byHour:''),meal_date,poor_intake:String(a?.alert_type||'').toLowerCase()==='meal intake'};
  };
  const clearTaskNavigationContext = () => {
    try{sessionStorage.removeItem(TASK_NAVIGATION_KEY)}catch(_error){}
  };

  const finishSuccessfulAction = ({
    close,
    returnPage,
    onNavigate,
    delay=650,
    refresh
  }={}) => {
    try{
      if(typeof close==='function')close();
    }catch(error){
      console.warn('Action window could not be closed cleanly.',error);
    }
    try{
      if(typeof refresh==='function')refresh();
    }catch(error){
      console.warn('Previous display refresh could not be started.',error);
    }
    if(returnPage&&typeof onNavigate==='function'){
      setTimeout(()=>onNavigate(returnPage),delay);
      return true;
    }
    return false;
  };

  const returnAfterSuccessfulAction = (returnPage,onNavigate,delay=650) =>
    finishSuccessfulAction({returnPage,onNavigate,delay});


  const closeTopActionPopup = () => {
    const popups=[...document.querySelectorAll('.modal-backdrop')]
      .filter(node=>{
        const style=window.getComputedStyle(node);
        return style.display!=='none'&&
          style.visibility!=='hidden'&&
          node.getAttribute('data-manual-close')!=='true';
      });
    const popup=popups.at(-1);
    if(!popup)return false;

    const closeButton=
      popup.querySelector('button.close')||
      [...popup.querySelectorAll('button')].find(button=>
        ['close','cancel','done','back'].includes(
          String(button.textContent||'').trim().toLowerCase()
        )
      );

    if(closeButton){
      closeButton.click();
      return true;
    }

    popup.dispatchEvent(new KeyboardEvent('keydown',{
      key:'Escape',
      code:'Escape',
      bubbles:true
    }));
    return true;
  };

  const isSuccessfulEntryElement = node => {
    if(!(node instanceof Element))return false;
    if(node.matches('.samara-toast.success,.samara-toast.warning,.message.success,.toast.success,.toast.warning,[data-toast-type="success"],[data-toast-type="warning"]'))return true;
    return Boolean(node.querySelector('.samara-toast.success,.samara-toast.warning,.message.success,.toast.success,.toast.warning,[data-toast-type="success"],[data-toast-type="warning"]'));
  };



  // v2.14.34: red error panels across the ERP (".message.error") show simple English.
  const samaraTechnicalError=/violates|constraint|duplicate key|row-level security|permission denied|jwt|refresh token|failed to fetch|networkerror|invalid input syntax|does not exist|schema cache|non-2xx|null value in column|value too long|out of range/i;
  function samaraTranslateErrorNode(el){
    try{
      if(!(el instanceof Element))return;
      const targets=el.matches('.message.error,.admission-error-toast span')?[el]:[...el.querySelectorAll('.message.error,.admission-error-toast span')];
      for(const node of targets){
        for(const child of node.childNodes){
          if(child.nodeType===3&&samaraTechnicalError.test(child.nodeValue||'')){
            const friendly=samaraFriendlyError(child.nodeValue);
            if(friendly!==child.nodeValue)child.nodeValue=friendly;
          }
        }
      }
    }catch(_){}
  }
  try{
    const samaraErrorObserver=new MutationObserver(list=>{for(const m of list){if(m.type==='characterData'&&m.target.parentElement)samaraTranslateErrorNode(m.target.parentElement);m.addedNodes&&m.addedNodes.forEach(n=>samaraTranslateErrorNode(n.nodeType===3?n.parentElement:n));}});
    const startObserver=()=>samaraErrorObserver.observe(document.body,{childList:true,subtree:true,characterData:true});
    if(document.body)startObserver();else document.addEventListener('DOMContentLoaded',startObserver);
  }catch(_){}

  const showSamaraActionToast = (type='success',title='',text='') => {
    try{
      document.querySelectorAll('.samara-save-confirmation').forEach(node=>node.remove());

      const warning=type==='warning'||(type==='success'&&/saved with warning|saved for review|warning/i.test(String(text)));
      const success=type==='success'&&!warning;
      const tone=success?'success':warning?'warning':'error';
      const overlay=document.createElement('div');
      overlay.className=`samara-save-confirmation ${tone}`;
      overlay.setAttribute('role',success?'status':'alert');
      overlay.setAttribute('aria-live',success?'polite':'assertive');

      // INLINE layout is deliberate: confirmation must remain visible even if
      // an old stylesheet, browser cache or React re-render is present.
      Object.assign(overlay.style,{
        position:'fixed',
        left:'0',right:'0',top:'0',
        zIndex:'2147483647',
        display:'flex',
        justifyContent:'center',
        alignItems:'flex-start',
        padding:'max(12px, env(safe-area-inset-top)) 10px 10px',
        pointerEvents:'none'
      });

      const card=document.createElement('div');
      Object.assign(card.style,{
        width:'min(560px, calc(100vw - 20px))',
        boxSizing:'border-box',
        display:'grid',
        gridTemplateColumns:'46px minmax(0,1fr) 54px',
        alignItems:'center',
        gap:'11px',
        minHeight:'92px',
        padding:'14px',
        borderRadius:'17px',
        background:success
          ?'linear-gradient(110deg,#087f5b,#0b9b73,#17b978)'
          :warning
            ?'linear-gradient(110deg,#9a5b00,#c47b00,#e0a51b)'
            :'linear-gradient(110deg,#a7192b,#c9293c,#df4050)',
        color:'#ffffff',
        border:'2px solid rgba(255,255,255,.50)',
        boxShadow:'0 18px 48px rgba(0,0,0,.30)',
        pointerEvents:'auto',
        fontFamily:"Inter, system-ui, -apple-system, 'Segoe UI', sans-serif"
      });

      const icon=document.createElement('div');
      icon.textContent=success?'✓':'!';
      Object.assign(icon.style,{
        width:'44px',height:'44px',
        display:'flex',alignItems:'center',justifyContent:'center',
        borderRadius:'50%',
        background:'rgba(255,255,255,.20)',
        color:'#fff',
        fontSize:'27px',
        fontWeight:'900'
      });

      const copy=document.createElement('div');
      Object.assign(copy.style,{display:'grid',gap:'4px',minWidth:'0'});
      const strong=document.createElement('strong');
      strong.textContent=title||(success?'Success':warning?'Saved with warning':'Action failed');
      Object.assign(strong.style,{color:'#fff',fontSize:'17px',lineHeight:'1.15',fontWeight:'900'});
      const span=document.createElement('span');
      span.textContent=(!success&&!warning&&text)?samaraFriendlyError(text):(text||(success?'Your entry has been saved successfully.':warning?'The entry was saved and requires review.':'Please check the entry and try again.'));
      Object.assign(span.style,{color:'#fff',fontSize:'13px',lineHeight:'1.35',fontWeight:'600'});
      copy.append(strong,span);

      const ok=document.createElement('button');
      ok.type='button';
      ok.textContent='OK';
      Object.assign(ok.style,{
        minWidth:'50px',minHeight:'42px',
        padding:'7px 9px',
        border:'1px solid rgba(255,255,255,.60)',
        borderRadius:'11px',
        background:'rgba(255,255,255,.16)',
        color:'#fff',
        fontSize:'14px',
        fontWeight:'900',
        cursor:'pointer'
      });
      ok.addEventListener('click',()=>overlay.remove());

      card.append(icon,copy,ok);
      overlay.appendChild(card);
      document.body.appendChild(overlay);

      try{
        if(navigator.vibrate)navigator.vibrate(success?[80]:[100,60,100]);
      }catch(_){}

      // Staff must have time to notice it. They may dismiss immediately with OK.
      window.setTimeout(()=>{if(overlay.isConnected)overlay.remove();},10000);
    }catch(error){
      console.error('Save confirmation display failed:',error);
      // Last-resort feedback if the DOM notification itself cannot be built.
      try{window.alert(`${title||'Samara Care ERP'}\n${text||''}`)}catch(_){}
    }
  };

