  // v2.11.36: Global Tamil / English voice input for frontline nursing narrative fields.
  // Adds a compact Voice button beside free-text nursing fields without changing existing forms.
  function GlobalNursingVoiceInput({profile,page}){
    const spotAssessment=page==='Spot Assessment';
    const enabled=Boolean(profile?.id);
    const [target,setTarget]=React.useState(null);
    const [open,setOpen]=React.useState(false);
    const [listening,setListening]=React.useState(false);
    const [processing,setProcessing]=React.useState(false);
    const [message,setMessage]=React.useState('');
    const [transcript,setTranscript]=React.useState('');
    const [reviewText,setReviewText]=React.useState('');
    const recognitionRef=React.useRef(null);
    const recorderRef=React.useRef(null);
    const streamRef=React.useRef(null);
    const chunksRef=React.useRef([]);
    const langRef=React.useRef('ta-IN');
    const audioBlobRef=React.useRef(null);

    function eligible(el){
      if(!enabled||!el||el.disabled||el.readOnly)return false;
      if(el.dataset?.samaraVoice==='off'||el.closest('.samara-voice-modal'))return false;
      if(spotAssessment)return Boolean(el.closest('.spot-assessment')&&el.dataset?.samaraVoice==='on');
      const type=String(el.getAttribute('type')||'text').toLowerCase();
      if(el.tagName==='INPUT'&&!['text','search'].includes(type))return false;
      const bits=[el.name,el.id,el.placeholder,el.getAttribute('aria-label'),el.closest('label')?.innerText,el.parentElement?.querySelector(':scope > label')?.innerText].filter(Boolean).join(' ').toLowerCase();
      if(/search|username|login|password|email|mobile|phone|contact no|patient id|employee id|mr no|room no|bed no|reference no|payment reference/.test(bits))return false;
      if(el.tagName==='TEXTAREA')return true;
      return /remark|note|instruction|summary|handover|hand over|observation|reason|description|detail|advice|complaint|finding|action taken|follow.?up|precaution|restriction|incident|diet|care plan|special|comment|clinical|doctor|procedure|diagnosis|allerg|referred|request|transport|belonging|condition|status note/.test(bits);
    }

    function addButtons(){
      if(!enabled)return;
      document.querySelectorAll('textarea,input[type="text"],input:not([type])').forEach(el=>{
        if(!eligible(el)||el.dataset.samaraVoiceReady==='1')return;
        el.dataset.samaraVoiceReady='1';
        const btn=document.createElement('button');
        btn.type='button';btn.className='samara-global-voice-btn';btn.innerHTML='🎤 Voice';
        btn.title='Tamil / English voice input';btn.setAttribute('aria-label','Tamil or English voice input');
        btn.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();audioBlobRef.current=null;setTarget(el);setTranscript('');setReviewText('');setMessage('');setOpen(true)});
        el.insertAdjacentElement('afterend',btn);
        window.SamaraDictation?.attach(btn,el);
      });
    }

    React.useEffect(()=>{
      if(!enabled)return;
      addButtons();
      let disposed=false,pending=null;
      const ob=new MutationObserver(()=>{if(pending!==null)return;pending=window.setTimeout(()=>{pending=null;if(!disposed)addButtons()},40)});
      ob.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['disabled','readonly']});
      return()=>{disposed=true;clearTimeout(pending);ob.disconnect();window.SamaraDictation?.stop();document.querySelectorAll('.samara-global-voice-btn').forEach(x=>x.remove());document.querySelectorAll('[data-samara-voice-ready="1"]').forEach(x=>delete x.dataset.samaraVoiceReady)};
    },[enabled,spotAssessment]);

    function stop(){
      try{recognitionRef.current?.stop?.()}catch(_){} recognitionRef.current=null;
      try{if(recorderRef.current&&recorderRef.current.state!=='inactive')recorderRef.current.stop()}catch(_){}
      try{streamRef.current?.getTracks?.().forEach(t=>t.stop())}catch(_){}
      streamRef.current=null;setListening(false);
    }
    function nativeSet(el,value){
      if(!el)return;
      const proto=el.tagName==='TEXTAREA'?window.HTMLTextAreaElement.prototype:window.HTMLInputElement.prototype;
      const setter=Object.getOwnPropertyDescriptor(proto,'value')?.set;
      if(setter)setter.call(el,value);else el.value=value;
      el.dispatchEvent(new Event('input',{bubbles:true}));
      el.dispatchEvent(new Event('change',{bubbles:true}));
      try{el.focus();el.setSelectionRange(value.length,value.length)}catch(_){}
    }
    function appendText(text){
      const clean=String(text||'').trim();if(!clean||!target)return;
      const old=String(target.value||'').trim();
      nativeSet(target,old?`${old}${/[.!?]$/.test(old)?' ':' — '}${clean}`:clean);
    }
    function stageText(text){
      const clean=String(text||'').trim();
      if(!clean){setMessage('No usable text was returned. Please record again.');return}
      setReviewText(clean);
      setMessage('Review and edit the text below. It has not yet been entered into the form.');
    }
    function useReviewedText(){
      if(!target?.isConnected||target.disabled||target.readOnly){setMessage('This field is no longer available. Close Voice Input and reopen it from the assessment.');return}
      const clean=String(reviewText||'').trim();
      if(!clean){setMessage('Please enter or record the text before using it.');return}
      appendText(clean);
      stop();setOpen(false);setTarget(null);setTranscript('');setReviewText('');setMessage('');
    }
    function resultText(result,fallback=''){
      const f=result?.fields||{};
      const details=String(f.details||f.notes||f.description||'').trim();
      const title=String(f.title||f.subject||'').trim();
      if(details&&title&&!details.toLowerCase().startsWith(title.toLowerCase()))return `${title}. ${details}`;
      return details||title||String(result?.translated_text||result?.translation||fallback||'').trim();
    }
    async function sendTranscript(spoken,lang){
      setProcessing(true);
      try{
        if(String(lang).toLowerCase().startsWith('en')){stageText(spoken);return}
        setMessage('Converting Tamil speech to simple English…');
        const {data:{session}}=await client.auth.getSession();if(!session)throw new Error('Please sign in again.');
        const response=await fetch(`${cfg.supabaseUrl}/functions/v1/director-office-voice`,{method:'POST',headers:{'Authorization':`Bearer ${session.access_token}`,'apikey':cfg.supabasePublishableKey,'Content-Type':'application/json'},body:JSON.stringify({transcript:spoken,spoken_language:lang,current_form_type:'Nursing Note',current_task_kind:'Clinical Note',now_iso:new Date().toISOString(),timezone:'Asia/Kolkata'})});
        const result=await response.json().catch(()=>({error:'Unable to read voice response'}));
        if(!response.ok||result.error)throw new Error(result.error||'Unable to convert Tamil speech.');
        const text=resultText(result,'');if(!text)throw new Error('No English text was returned.');
        stageText(text);
      }catch(error){setMessage(`Tamil speech was captured, but English conversion could not complete. ${error.message||''}`)}
      finally{setProcessing(false)}
    }
    function bestMime(){
      for(const x of ['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus']){try{if(window.MediaRecorder&&MediaRecorder.isTypeSupported?.(x))return x}catch(_){}}return '';
    }
    async function sendAudio(blob,lang,providerPreference='auto'){
      if(!blob)return setMessage('The previous recording is not available. Please record again.');
      audioBlobRef.current=blob;
      setProcessing(true);setMessage(providerPreference==='openai'?'Trying OpenAI…':providerPreference==='gemini'?'Trying Gemini again…':'Trying Gemini first; OpenAI will be used automatically if needed…');
      try{
        const {data:{session}}=await client.auth.getSession();if(!session)throw new Error('Please sign in again.');
        const ext=(blob.type||'').includes('mp4')?'m4a':(blob.type||'').includes('ogg')?'ogg':'webm';
        const fd=new FormData();fd.append('audio',blob,`nursing-voice.${ext}`);fd.append('spoken_language',lang);fd.append('current_form_type','Nursing Note');fd.append('current_task_kind','Clinical Note');fd.append('provider_preference',providerPreference);fd.append('now_iso',new Date().toISOString());fd.append('timezone','Asia/Kolkata');
        const response=await fetch(`${cfg.supabaseUrl}/functions/v1/director-office-voice`,{method:'POST',headers:{'Authorization':`Bearer ${session.access_token}`,'apikey':cfg.supabasePublishableKey},body:fd});
        const result=await response.json().catch(()=>({error:'Unable to read voice response'}));if(!response.ok||result.error)throw new Error(result.error||'Unable to process voice.');
        if(result?.transcript)setTranscript(String(result.transcript));
        const text=resultText(result,result?.transcript||'');if(!text)throw new Error('No text was returned.');stageText(text);
        setMessage(`Review and edit below. Processed by ${result?.provider_used||result?.provider||'voice service'}.`);
      }catch(error){setMessage(error.message||'Unable to process voice.')}finally{setProcessing(false)}
    }
    async function startRecorder(lang){
      if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setMessage('Microphone recording is not available in this browser.');return}
      try{
        const stream=await navigator.mediaDevices.getUserMedia({audio:true});streamRef.current=stream;chunksRef.current=[];langRef.current=lang;
        const mime=bestMime();const rec=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);recorderRef.current=rec;
        rec.ondataavailable=e=>{if(e.data?.size)chunksRef.current.push(e.data)};
        rec.onstop=async()=>{const blob=new Blob(chunksRef.current,{type:rec.mimeType||chunksRef.current[0]?.type||'audio/webm'});chunksRef.current=[];audioBlobRef.current=blob;try{stream.getTracks().forEach(t=>t.stop())}catch(_){}streamRef.current=null;recorderRef.current=null;setListening(false);if(blob.size<1000)return setMessage('No useful speech was captured. Please try again.');await sendAudio(blob,langRef.current,'auto')};
        rec.start();setListening(true);setMessage(lang==='ta-IN'?'🎤 Listening in Tamil… Tap Stop when finished.':'🎤 Listening in English… Tap Stop when finished.');
      }catch(error){setListening(false);setMessage(error?.name==='NotAllowedError'?'Microphone permission is blocked. Please allow microphone access for Samara Care.':(error.message||'Unable to start microphone.'))}
    }
    function start(lang){
      if(listening||processing)return;
      setTranscript('');setReviewText('');setMessage('');
      // MediaRecorder remains active across sentences and natural pauses until
      // the nurse presses Stop. SpeechRecognition is retained only as fallback.
      if(navigator.mediaDevices?.getUserMedia&&window.MediaRecorder)return startRecorder(lang);
      const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
      if(!SR)return startRecorder(lang);
      try{
        const rec=new SR();recognitionRef.current=rec;rec.lang=lang;rec.interimResults=true;rec.continuous=true;rec.maxAlternatives=1;let finalText='';let latest='';let handled=false;
        rec.onstart=()=>{setListening(true);setMessage(lang==='ta-IN'?'🎤 Listening in Tamil…':'🎤 Listening in English…')};
        rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0]?.transcript||'';if(e.results[i].isFinal)finalText+=`${t} `;else interim+=t}latest=(finalText||interim).trim();setTranscript(latest)};
        const finish=()=>{if(handled)return;handled=true;setListening(false);const spoken=(finalText||latest).trim();if(spoken)sendTranscript(spoken,lang);else setMessage('No speech was captured. Please try again.')};
        rec.onerror=e=>{setListening(false);if((e?.error==='not-allowed'||e?.error==='service-not-allowed')){handled=true;setMessage('Microphone / speech permission is blocked. Please allow microphone access.')}else if(!latest&&!finalText){handled=true;startRecorder(lang)}};
        rec.onend=finish;rec.start();
      }catch(_){startRecorder(lang)}
    }
    function close(){stop();setOpen(false);setTarget(null);setTranscript('');setReviewText('');setMessage('');audioBlobRef.current=null}
    if(!enabled||!open)return null;
    return h('div',{className:'samara-voice-modal-backdrop',onClick:e=>{if(e.target===e.currentTarget)close()}},
      h('div',{className:'samara-voice-modal'},
        h('div',{className:'samara-voice-modal-head'},h('div',null,h('strong',null,'🎤 Voice Input'),h('small',null,'Speak naturally. Tamil is converted to simple English.')),h('button',{type:'button',className:'close',onClick:close},'×')),
        listening?h('button',{type:'button',className:'btn btn-danger samara-voice-stop',onClick:stop},'■ Stop Recording'):
          reviewText?h('div',{className:'samara-voice-review-actions'},
            h('button',{type:'button',className:'btn btn-primary',onClick:useReviewedText},'✓ Use This Text'),
            h('button',{type:'button',className:'btn btn-secondary',onClick:()=>{setTranscript('');setReviewText('');setMessage('')}},'🎤 Record Again'),
            h('button',{type:'button',className:'btn btn-secondary',onClick:close},'Cancel')
          ):h('div',{className:'samara-voice-actions'},h('button',{type:'button',className:'btn btn-primary',disabled:processing,onClick:()=>start('ta-IN')},processing?'Processing…':'🎤 Speak Tamil'),h('button',{type:'button',className:'btn btn-secondary',disabled:processing,onClick:()=>start('en-IN')},'🎤 Speak English')),
        transcript&&h('div',{className:'samara-voice-transcript'},h('small',null,'Heard'),h('div',null,transcript)),
        reviewText&&h('div',{className:'samara-voice-review'},h('label',null,'Review and edit before using'),h('textarea',{rows:5,value:reviewText,onChange:e=>setReviewText(e.target.value)})),
        reviewText&&audioBlobRef.current?h('div',{className:'samara-voice-provider-actions'},
          h('button',{type:'button',className:'btn btn-secondary',disabled:processing,onClick:()=>sendAudio(audioBlobRef.current,langRef.current,'gemini')},processing?'Processing…':'Try Gemini Again'),
          h('button',{type:'button',className:'btn btn-secondary',disabled:processing,onClick:()=>sendAudio(audioBlobRef.current,langRef.current,'openai')},processing?'Processing…':'Try OpenAI Instead')
        ):null,
        message&&h('div',{className:'samara-voice-message'},message),
        h('div',{className:'samara-voice-note'},reviewText?'Correct any word, then tap Use This Text. Save / Submit remains a separate action.':'Recording continues across sentences and pauses until Stop Recording is pressed.')
      )
    );
  }

  function TamilAssist({text,context='Clinical Instruction'}){
    const source=String(text||'').trim();
    const [tamil,setTamil]=React.useState('');
    const [open,setOpen]=React.useState(false);
    const [loading,setLoading]=React.useState(false);
    const [error,setError]=React.useState('');

    React.useEffect(()=>{setTamil('');setOpen(false);setError('')},[source]);
    async function sourceHash(value){
      const bytes=new TextEncoder().encode(value);
      const digest=await crypto.subtle.digest('SHA-256',bytes);
      return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');
    }
    async function translate(){
      if(!source||loading)return;
      if(tamil){setOpen(true);return}
      setLoading(true);setError('');
      try{
        // Include the translation-style version so older machine-Tamil cache entries
        // are bypassed automatically after a practical-language prompt update.
        const hash=await sourceHash(`practical-tamil-v2|${source}`);
        const {data:cached}=await client.from('staff_tamil_translations').select('tamil_text').eq('source_hash',hash).maybeSingle();
        if(cached?.tamil_text){setTamil(cached.tamil_text);setOpen(true);return}
        const {data:{session}}=await client.auth.getSession();if(!session)throw new Error('Please sign in again.');
        const response=await fetch(`${cfg.supabaseUrl}/functions/v1/staff-translate-tamil`,{method:'POST',headers:{'Authorization':`Bearer ${session.access_token}`,'apikey':cfg.supabasePublishableKey,'Content-Type':'application/json'},body:JSON.stringify({text:source,context})});
        const raw=await response.text();let result={};try{result=JSON.parse(raw)}catch(_){throw new Error('Translation service returned an unreadable response.')}
        if(!response.ok||result.error)throw new Error(result.error||'Tamil translation could not be completed.');
        const translated=String(result.tamil_text||'').trim();if(!translated)throw new Error('No Tamil translation was returned.');
        setTamil(translated);setOpen(true);
        await client.from('staff_tamil_translations').upsert({source_hash:hash,source_text:source,tamil_text:translated,clinical_context:context,created_by:session.user.id},{onConflict:'source_hash'});
      }catch(err){setError(err.message||'Unable to translate now.')}finally{setLoading(false)}
    }
    function speak(){
      if(!tamil||!window.speechSynthesis)return setError('Tamil audio is not available on this device.');
      window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(tamil);utterance.lang='ta-IN';utterance.rate=.9;
      const voices=window.speechSynthesis.getVoices?.()||[];const voice=voices.find(v=>String(v.lang||'').toLowerCase().startsWith('ta'));if(voice)utterance.voice=voice;
      window.speechSynthesis.speak(utterance);
    }
    if(!source||source==='—')return null;
    return h('div',{className:'staff-tamil-assist'},
      !open?h('button',{type:'button',className:'staff-tamil-button',disabled:loading,onClick:translate},loading?'மொழிபெயர்க்கிறது…':'தமிழில் பார்க்க'):null,
      open?h('div',{className:'staff-tamil-panel'},
        h('div',{className:'staff-tamil-head'},h('strong',null,'தமிழ் மொழிபெயர்ப்பு'),h('div',{className:'actions'},h('button',{type:'button',onClick:speak},'🔊 தமிழில் கேட்க'),h('button',{type:'button',onClick:()=>{window.speechSynthesis?.cancel?.();setOpen(false)}},'தமிழை மறைக்க'))),
        h('p',{lang:'ta'},tamil),
        h('small',null,'புரிதலுக்காக மட்டும். மேலே உள்ள ஆங்கிலப் பதிவே அதிகாரப்பூர்வ மருத்துவப் பதிவு.')
      ):null,
      error?h('div',{className:'staff-tamil-error'},error,h('button',{type:'button',onClick:translate},'Try again')):null
    );
  }

  function GeneralHandoverWorklist({profile}){
    const [rows,setRows]=React.useState([]);
    const [loading,setLoading]=React.useState(true);
    const [message,setMessage]=React.useState('');
    const [busyId,setBusyId]=React.useState('');
    const priorityRank={Critical:0,Important:1,Routine:2};

    async function load(){
      const {data,error}=await client.from('general_handover_tasks')
        .select('*')
        .in('status',['Pending','In Progress'])
        .order('created_at',{ascending:false})
        .limit(100);
      if(error){
        console.warn('General handover worklist could not be loaded:',error.message);
        setRows([]);setMessage('General handover worklist is unavailable. Please install the accompanying SQL once.');setLoading(false);return;
      }
      const sorted=[...(data||[])].sort((a,b)=>(priorityRank[a.priority]??3)-(priorityRank[b.priority]??3)||new Date(a.created_at||0)-new Date(b.created_at||0));
      setRows(sorted);setMessage('');setLoading(false);
    }

    React.useEffect(()=>{
      load();
      const ch=client.channel(`general-handover-${profile?.id||'user'}`)
        .on('postgres_changes',{event:'*',schema:'public',table:'general_handover_tasks'},load)
        .subscribe();
      return()=>client.removeChannel(ch);
    },[profile?.id]);

    async function setStatus(row,status){
      if(busyId)return;
      setBusyId(row.id);setMessage('');
      const updates={status,updated_at:new Date().toISOString()};
      if(status==='Completed'){updates.completed_by=profile.id;updates.completed_at=new Date().toISOString()}
      const {error}=await client.from('general_handover_tasks').update(updates).eq('id',row.id);
      if(error)setMessage(error.message||'Unable to update the general task.');
      else{
        writeAuditEvent(`General Handover Task ${status}`,'General Handover',row.id,{department:row.department,task_text:row.task_text,status},'Success');
        await load();
      }
      setBusyId('');
    }

    return h(Section,{title:`General Priority Worklist${rows.length?` (${rows.length})`:''}`,subtitle:'Housekeeping, Maintenance and Operations tasks from Shift Handover'},
      h('div',{className:'general-handover-toolbar'},
        h('span',null,'Visible to all authorised role players'),
        h('button',{type:'button',className:'btn btn-secondary',onClick:load,disabled:loading},loading?'Loading…':'Refresh')
      ),
      message&&h('div',{className:'message error'},message),
      !loading&&!message&&!rows.length?h('div',{className:'clinical-empty'},'No open general handover tasks.'):
      h('div',{className:'general-handover-list'},rows.map((row,index)=>
        h('div',{className:`general-handover-row priority-${String(row.priority||'Routine').toLowerCase()}`,key:row.id},
          h('span',{className:'general-handover-number'},index+1),
          h('div',{className:'general-handover-detail'},
            h('div',{className:'general-handover-meta'},
              h('strong',null,row.department||'Operations'),
              h('span',{className:'general-handover-priority'},row.priority||'Routine'),
              h('span',{className:'general-handover-status'},row.status||'Pending')
            ),
            h('p',null,row.task_text),
            h(TamilAssist,{text:row.task_text,context:'General Handover'}),
            h('small',null,`${row.shift||'Shift'} · ${fmt(row.created_at)}`)
          ),
          h('div',{className:'general-handover-actions'},
            row.status==='Pending'&&h('button',{type:'button',className:'btn btn-secondary',disabled:busyId===row.id,onClick:()=>setStatus(row,'In Progress')},'Start'),
            h('button',{type:'button',className:'btn btn-primary',disabled:busyId===row.id,onClick:()=>setStatus(row,'Completed')},busyId===row.id?'Saving…':'Complete')
          )
        )
      ))
    );
  }

  function SystemMaintenance({profile}){
    const [checking,setChecking]=React.useState(false);
    const isAdmin=profile?.role==='Admin';
    const runUpdateCheck=()=>{
      setChecking(true);
      try{
        if(typeof window.samaraCheckForUpdate==='function')window.samaraCheckForUpdate();
        else samaraOpenAppHelp();
      }finally{window.setTimeout(()=>setChecking(false),1400)}
    };
    if(!isAdmin)return h('div',{className:'section-card'},h('h3',null,'System Maintenance'),h('p',null,'This page is restricted to the Administrator.'));
    const serviceWorkerState=!('serviceWorker' in navigator)?'Not supported':(navigator.serviceWorker.controller?'Active':'Not controlling this page');
    const online=navigator.onLine?'Online':'Offline';
    return h('div',{className:'stack system-maintenance-page'},
      h('div',{className:'page-hero system-maintenance-hero'},
        h('div',null,h('div',{className:'eyebrow'},'ADMIN / APPLICATION'),h('h2',null,'System Maintenance'),h('p',null,'Safe application update, recovery and diagnostic controls. Patient, clinical and billing records are not altered here.'))
      ),
      h('div',{className:'system-maintenance-grid'},
        h('section',{className:'section-card system-maintenance-card'},h('span',{className:'system-maintenance-icon'},'↻'),h('h3',null,'Application Update'),h('p',null,'Check whether a newer Samara ERP build is available.'),h('button',{type:'button',className:'btn btn-primary',disabled:checking,onClick:runUpdateCheck},checking?'Checking…':'Check for Updates')),
        h('section',{className:'section-card system-maintenance-card'},h('span',{className:'system-maintenance-icon'},'⚙'),h('h3',null,'App Help & Repair'),h('p',null,'Open the safe reload and cache-repair controls. Supabase data will not be deleted.'),h('button',{type:'button',className:'btn btn-secondary',onClick:samaraOpenAppHelp},'Open App Help / Repair')),
        h('section',{className:'section-card system-maintenance-card'},h('span',{className:'system-maintenance-icon'},'⟳'),h('h3',null,'Reload Application'),h('p',null,'Reload the current application files without changing stored records.'),h('button',{type:'button',className:'btn btn-secondary',onClick:()=>window.location.reload()},'Reload Samara ERP'))
      ),
      h('section',{className:'section-card system-information-card'},
        h('h3',null,'System Information'),
        h('div',{className:'system-information-grid'},
          h('div',null,h('small',null,'ERP Version'),h('strong',null,APP_VERSION)),
          h('div',null,h('small',null,'Build'),h('strong',null,APP_BUILD_DATE)),
          h('div',null,h('small',null,'Schema'),h('strong',null,APP_SCHEMA_VERSION)),
          h('div',null,h('small',null,'Network'),h('strong',{className:navigator.onLine?'system-ok':'system-warn'},online)),
          h('div',null,h('small',null,'Service Worker'),h('strong',null,serviceWorkerState)),
          h('div',null,h('small',null,'Signed-in Role'),h('strong',null,profile.role))
        )
      )
    );
  }

  // 2.16.43: System Health (Admin only) — the ERP's automatic fault log (table client_errors, SQL 137 + 219).
  // Faults are grouped (same kind + same message), newest first. Filters use Apply. Every group opens its full details
  // (staff, role, page, time, version, device, detail). Admin can mark a group as resolved with a short note.
  // Recorded automatically: page crashes, JavaScript errors, failed saves, server errors, unreachable server, slow
  // requests (> 8 s) and Talk to Guest events. No Guest names, audio or clinical details are stored.
  const SYSTEM_HEALTH_KINDS={
    'page-crash':['Screen crashed','A page stopped working and showed "This page had a problem".'],
    'app-crash':['App crashed','The whole app stopped working.'],
    'window-error':['Program error','An error in the app code (the page kept working).'],
    'unhandled-rejection':['Unfinished action','An action failed in the background.'],
    'save-failed':['Save refused','The database refused a save (permission or data rule).'],
    'server-error':['Server error','The server failed to answer correctly.'],
    'network-error':['Server unreachable','The phone could not reach the server (internet).'],
    'offline':['Phone offline','The phone had no internet.'],
    'slow-request':['Slow screen','A request took longer than 8 seconds.'],
    'ttg-live-fallback':['Talk to Guest: Live unavailable','Live mode could not start or kept failing; Standard mode was used.'],
    'ttg-live-drop':['Talk to Guest: Live dropped','The live connection dropped and reconnected.'],
    'ttg-live-stall':['Talk to Guest: speech missed','People were speaking but Live heard nothing; it restarted itself.'],
    'ttg-echo':['Talk to Guest: echo','The translation was heard again by the microphone; muting was made stronger automatically.'],
    'ttg-auto-pause':['Talk to Guest: wait increased','Speech was cut too often; the wait after the speaker stops was increased automatically.'],
    'ttg-not-caught':['Talk to Guest: not understood','Several sentences in a row were not understood.'],
    'ttg-slow':['Talk to Guest: slow translation','A translation took longer than 7 seconds.'],
    'ttg-error':['Talk to Guest: error','Translation failed.'],
    'ttg-mic':['Talk to Guest: microphone','The microphone could not be opened.']
  };
  function SystemHealth({profile}){
    const isAdmin=profile?.role==='Admin';
    const [period,setPeriod]=React.useState('week');
    const [from,setFrom]=React.useState('');
    const [to,setTo]=React.useState('');
    const [showResolved,setShowResolved]=React.useState('open');
    const filters=useAppliedFilters({period,from,to,showResolved});
    const [rows,setRows]=React.useState([]);
    const [staff,setStaff]=React.useState({});
    const [loading,setLoading]=React.useState(false);
    const [error,setError]=React.useState('');
    const [open,setOpen]=React.useState(null);
    const [note,setNote]=React.useState('');
    const [saving,setSaving]=React.useState(false);
    const [canResolve,setCanResolve]=React.useState(true);
    const range=f=>{
      const now=new Date(),start=new Date(now);start.setHours(0,0,0,0);
      if(f.period==='today')return [start,now];
      if(f.period==='week'){start.setDate(start.getDate()-6);return [start,now];}
      if(f.period==='month'){start.setDate(1);return [start,now];}
      const a=f.from?new Date(`${f.from}T00:00:00`):start,b=f.to?new Date(`${f.to}T23:59:59`):now;return [a,b];
    };
    const load=React.useCallback(async()=>{
      if(!isAdmin)return;setLoading(true);setError('');
      try{
        const [a,b]=range(filters.applied);
        const {data,error:e}=await client.from('client_errors').select('*').gte('created_at',a.toISOString()).lte('created_at',b.toISOString()).order('created_at',{ascending:false}).limit(2000);
        if(e)throw e;
        const list=data||[];setRows(list);
        setCanResolve(!list.length||list.some(x=>Object.prototype.hasOwnProperty.call(x,'resolved_at'))); // column exists once SQL 219 is run
        const ids=[...new Set(list.map(r=>r.user_id).filter(Boolean))];
        if(ids.length){const {data:ps}=await client.from('profiles').select('id,auth_user_id,full_name,role').or(`id.in.(${ids.join(',')}),auth_user_id.in.(${ids.join(',')})`);const m={};(ps||[]).forEach(p=>{m[p.id]=p;if(p.auth_user_id)m[p.auth_user_id]=p;});setStaff(m);}
      }catch(e){setError(e.message||'Could not load the fault log.');}
      finally{setLoading(false);}
    },[isAdmin,JSON.stringify(filters.applied)]);
    React.useEffect(()=>{load();},[load]);
    if(!isAdmin)return h('div',{className:'section-card'},h('h3',null,'System Health'),h('p',null,'This page is restricted to the Administrator.'));

    // Group same kind + same message (numbers inside messages ignored), newest first.
    const norm=t=>String(t||'').replace(/\d+(\.\d+)?/g,'#').slice(0,220);
    const groups=[];const byKey=new Map();
    for(const r of rows){
      const k=r.kind+'|'+norm(r.message);let g=byKey.get(k);
      if(!g){g={key:k,kind:r.kind,message:r.message,items:[],pages:new Set(),roles:new Set(),versions:new Set(),users:new Set()};byKey.set(k,g);groups.push(g);}
      g.items.push(r);if(r.page)g.pages.add(r.page);if(r.app_version)g.versions.add(r.app_version);if(r.user_id){g.users.add(r.user_id);const p=staff[r.user_id];if(p?.role)g.roles.add(p.role);}
    }
    groups.forEach(g=>{g.open=g.items.filter(x=>!x.resolved_at).length;g.last=g.items[0].created_at;g.first=g.items[g.items.length-1].created_at;});
    const shown=groups.filter(g=>filters.applied.showResolved==='all'||(filters.applied.showResolved==='open'?g.open>0:g.open===0));
    const label=k=>(SYSTEM_HEALTH_KINDS[k]||[k||'Fault'])[0];
    const explain=k=>(SYSTEM_HEALTH_KINDS[k]||[,''])[1];
    const tone=k=>/crash|server|save-failed|ttg-error|fallback/.test(k||'')?'#b01264':/slow|stall|echo|not-caught|network|offline|drop/.test(k||'')?'#b7791f':'#087667';
    const openGroups=groups.filter(g=>g.open>0).length;
    const people=new Set(rows.map(r=>r.user_id).filter(Boolean)).size;
    const topPage=(()=>{const c={};rows.forEach(r=>{if(r.page)c[r.page]=(c[r.page]||0)+1;});return Object.entries(c).sort((a,b)=>b[1]-a[1])[0];})();

    async function resolve(g){
      if(!note.trim()){setError('Please write a short note on what was fixed.');return;}
      setSaving(true);setError('');
      try{
        const {data:{user}}=await client.auth.getUser();
        const ids=g.items.filter(x=>!x.resolved_at).map(x=>x.id);
        for(let i=0;i<ids.length;i+=100){const {error:e}=await client.from('client_errors').update({resolved_at:new Date().toISOString(),resolved_by:user?.id||null,resolution_note:note.trim().slice(0,500)}).in('id',ids.slice(i,i+100));if(e)throw e;}
        setNote('');setOpen(null);await load();
      }catch(e){setError(/resolved|column|permission|policy/i.test(e.message||'')?'Marking as resolved needs SQL 219 to be run once in Supabase.':(e.message||'Could not save.'));}
      finally{setSaving(false);}
    }
    const tile=(title,value,sub,color)=>h('div',{className:'section-card',style:{padding:14,borderLeft:`5px solid ${color||'#5d1039'}`}},h('small',null,title),h('div',{style:{fontSize:26,fontWeight:800,margin:'4px 0'}},value),h('small',{style:{color:'#78636f'}},sub));
    const g=open&&groups.find(x=>x.key===open);

    return h('div',{className:'stack system-health-page'},
      h('div',{className:'page-hero'},h('div',null,h('div',{className:'eyebrow'},'ADMIN / APPLICATION'),h('h2',null,'System Health'),
        h('p',null,'Problems the ERP noticed by itself while staff were using it: crashes, failed saves, server errors, slow screens and Talk to Guest issues. No Guest names, audio or medical details are recorded.'))),
      h('div',{style:{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(170px,1fr))',gap:12}},
        tile('Faults in period',rows.length,'all recorded events',rows.length?'#b7791f':'#087667'),
        tile('Open problems',openGroups,'different problems not yet resolved',openGroups?'#b01264':'#087667'),
        tile('Staff affected',people,'people who met a problem'),
        tile('Most affected page',topPage?topPage[0]:'—',topPage?topPage[1]+' events':'no events')),
      h('div',{className:'section-card',style:{display:'flex',gap:10,flexWrap:'wrap',alignItems:'flex-end'}},
        h('label',null,h('small',null,'Period'),h('select',{className:'input',value:period,onChange:e=>setPeriod(e.target.value)},
          h('option',{value:'today'},'Today'),h('option',{value:'week'},'This Week (7 days)'),h('option',{value:'month'},'This Month'),h('option',{value:'custom'},'Selected period'))),
        period==='custom'&&h('label',null,h('small',null,'From'),h('input',{className:'input',type:'date',value:from,onChange:e=>setFrom(e.target.value)})),
        period==='custom'&&h('label',null,h('small',null,'To'),h('input',{className:'input',type:'date',value:to,onChange:e=>setTo(e.target.value)})),
        h('label',null,h('small',null,'Show'),h('select',{className:'input',value:showResolved,onChange:e=>setShowResolved(e.target.value)},
          h('option',{value:'open'},'Open problems'),h('option',{value:'resolved'},'Resolved'),h('option',{value:'all'},'All'))),
        h(ApplyFilterButton,{dirty:filters.dirty,onApply:filters.apply}),
        h('button',{type:'button',className:'btn btn-secondary',onClick:load,disabled:loading},loading?'Loading…':'↻ Refresh')),
      error&&h('div',{className:'section-card',style:{color:'#b01264'}},error),
      !canResolve&&h('div',{className:'section-card',style:{background:'#fff6fa'}},'Run supabase/sql/219_system_health.sql once in Supabase → SQL Editor to enable details and "Mark resolved".'),
      !loading&&!shown.length&&h('div',{className:'section-card',style:{textAlign:'center',color:'#087667',padding:30}},filters.applied.showResolved==='open'?'✓ No open problems in this period.':'Nothing to show for this period.'),
      shown.map(x=>h('button',{key:x.key,type:'button',className:'section-card',onClick:()=>{setOpen(open===x.key?null:x.key);setNote('');},
          style:{textAlign:'left',width:'100%',cursor:'pointer',borderLeft:`5px solid ${tone(x.kind)}`,display:'block'}},
        h('div',{style:{display:'flex',justifyContent:'space-between',gap:10,flexWrap:'wrap'}},
          h('strong',{style:{color:tone(x.kind)}},label(x.kind)),
          h('span',{style:{fontWeight:700}},x.items.length+'×'+(x.open?'':' · resolved'))),
        h('div',{style:{margin:'6px 0',overflowWrap:'anywhere'}},x.message),
        h('small',{style:{color:'#78636f'}},'Last: '+formatDateTimeIN(x.last)+' · First: '+formatDateTimeIN(x.first)+(x.pages.size?' · Page: '+[...x.pages].slice(0,3).join(', '):'')+(x.roles.size?' · Role: '+[...x.roles].join(', '):'')))),
      g&&h('div',{className:'section-card',style:{border:'2px solid #5d1039'}},
        h('div',{style:{display:'flex',justifyContent:'space-between',gap:10}},h('h3',{style:{margin:0}},label(g.kind)),h('button',{type:'button',className:'btn btn-secondary',onClick:()=>setOpen(null)},'Close')),
        h('p',{style:{color:'#78636f'}},explain(g.kind)),
        h('p',{style:{overflowWrap:'anywhere'}},h('strong',null,'Message: '),g.message),
        h('p',null,h('strong',null,'Versions: '),[...g.versions].join(', ')||'—',' · ',h('strong',null,'Staff affected: '),g.users.size),
        g.open?h('div',{style:{display:'flex',gap:8,flexWrap:'wrap',margin:'10px 0'}},
          h('input',{className:'input',style:{flex:'1 1 260px'},placeholder:'What was fixed / why it can be closed',value:note,onChange:e=>setNote(e.target.value)}),
          h('button',{type:'button',className:'btn btn-primary',disabled:saving||!canResolve,onClick:()=>resolve(g)},saving?'Saving…':'✓ Mark resolved'))
          :h('p',{style:{color:'#087667'}},'Resolved'+(g.items[0].resolution_note?': '+g.items[0].resolution_note:'')+(g.items[0].resolved_at?' ('+formatDateTimeIN(g.items[0].resolved_at)+')':'')),
        h('div',{style:{overflowX:'auto'}},h('table',{className:'table'},
          h('thead',null,h('tr',null,['Date & time','Staff','Role','Page','Version','Details'].map(t=>h('th',{key:t},t)))),
          h('tbody',null,g.items.slice(0,50).map(r=>{const p=staff[r.user_id]||{};return h('tr',{key:r.id},
            h('td',null,formatDateTimeIN(r.created_at)),h('td',null,p.full_name||'—'),h('td',null,p.role||'—'),h('td',null,r.page||'—'),h('td',null,r.app_version||'—'),
            h('td',{style:{fontSize:12,maxWidth:420,overflowWrap:'anywhere'}},r.detail?Object.entries(r.detail).map(([k,v])=>k+': '+(typeof v==='object'?JSON.stringify(v):v)).join(' · '):(r.stack?String(r.stack).split('\n')[0]:'—')));})))),
        g.items.length>50&&h('small',null,'Showing the latest 50 of '+g.items.length+'.'))
    );
  }
