    const districtOptions=['All',...Array.from(new Set(rows.map(r=>String(r.district||'').trim()).filter(Boolean))).sort((a,b)=>a.localeCompare(b))];
    const admissionDateLabel=value=>value?formatDateIN(String(value).slice(0,10)):'—';
