      if(appliedMedicationFilter.period!=='All'){
        to=today;const days=appliedMedicationFilter.period==='Today'?0:appliedMedicationFilter.period==='7 Days'?6:29;from=addDaysISODate(today,-days);
      }
      from=from||to||today;to=to||from;
